              <ChatMessageList>
                {messages.map(m => (
                  <ChatMessage key={m.id} sender={m.sender}>
                    <ChatMessageBubble variant={m.sender === 'assistant' ? 'ghost' : 'filled'}>
                      {m.text}
                    </ChatMessageBubble>
                  </ChatMessage>
                ))}
              </ChatMessageList>
            </ChatLayout>
          </section>
          <ResizeHandle
            direction="horizontal"
            resizable={resizable}
            isAlwaysVisible={false}
            label="Resize chat and preview"
            xstyle={styles.handle}
