// narrow
await p.setViewportSize({width: 400, height: 800});
await p.waitForTimeout(800);
await p.screenshot({path: S + 'workspace-400-chat.png'});
await p.getByRole('radio', {name: 'Preview'}).click().catch(async () => p.getByText('Preview', {exact: true}).first().click());
await p.waitForTimeout(800);
await p.screenshot({path: S + 'workspace-400-preview.png'});
console.log('scrollWidth', await p.evaluate(() => document.documentElement.scrollWidth));
await b.close();
